// 1. Obtener datos originales del Webhook
const raw = $('RECIBE_DATA').first().json.body || $('RECIBE_DATA').first().json;

// 2. Obtener respuesta del Nodo IA
let aiText = "";
try {
  const aiRes = $input.first().json;
  if (aiRes.candidates && aiRes.candidates[0] && aiRes.candidates[0].content && aiRes.candidates[0].content.parts) {
    aiText = aiRes.candidates[0].content.parts[0].text || "";
  } else if (raw.ai_summary) {
    aiText = raw.ai_summary;
  }
} catch (e) {
  aiText = raw.ai_summary || "";
}

function stripHTML(text) {
  if (text === undefined || text === null) return "";
  return String(text)
    .replace(/<[^>]*>/g, "")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .trim();
}

const sevUpper = String(raw.severidad || raw.severity || raw.nivel || "").toUpperCase();
let emoji = "⚠️";
if (sevUpper.includes("CRITIC") || sevUpper.includes("CRÍT")) emoji = "🚨";
else if (sevUpper.includes("HIGH") || sevUpper.includes("ALTA")) emoji = "🛑";
else if (sevUpper.includes("INFO") || sevUpper.includes("BAJ")) emoji = "ℹ️";
else if (sevUpper.includes("MED")) emoji = "🟡";

const severidad = stripHTML(raw.severidad || raw.severity || raw.nivel) || "INFO";
const score = stripHTML(raw.risk_score || raw.score || "N/A");
const evento = stripHTML(raw.tipo_incidente || raw.event_type || raw.evento || "Incidente de Ciberseguridad");
const activo = stripHTML(raw.activo_afectado || raw.affected_asset || raw.recurso) || "Infraestructura Alma";
const control = stripHTML(raw.control_nist || raw.framework_nist || raw.nist_control || raw.nist) || "NIST CSF v2.0";
const ip = stripHTML(raw.responsable_ip || raw.usuario_ip || raw.ip || raw.ip_origen) || "N/A";
const sop = stripHTML(raw.sop_reference || raw.regla || raw.sop);
const detalle = stripHTML(raw.detalles || raw.details || raw.descripcion) || "Sin detalles adicionales.";
const accionOriginal = stripHTML(raw.accion_recomendada || raw.suggested_action || raw.recomendacion) || "Verificar protocolos de seguridad.";
const aiClean = stripHTML(aiText);
const id = stripHTML(raw.incident_id || raw.id_incidente) || "ALMA-SEC-" + Math.floor(Math.random() * 1000000);

// Ajuste temporal UTC-5 (Hora Perú)
const nowPeru = new Date(new Date().getTime() - (5 * 60 * 60 * 1000)).toISOString().replace('T', ' ').substring(0, 19) + ' UTC-5';
const timestamp = stripHTML(raw.timestamp || raw.fecha_hora) || nowPeru;

let seccionSop = sop ? `• Procedimiento: ${sop}\n` : "";
let seccionTimestamp = timestamp ? ` | ${timestamp}` : "";

let seccionIa = "";
if (aiClean && aiClean.length > 5) {
  seccionIa = `\n🧠 TRIAGE EN TIEMPO REAL (NODO IA - Google Gemini):\n${aiClean}\n`;
}

const mensajeFinal = `
${emoji} [ALERTA DE CIBERSEGURIDAD - SOAR]

• Evento: ${evento}
• Severidad: ${severidad} (Score: ${score}/10)
• Activo: ${activo}
• Control NIST: ${control}
${seccionSop}• IP/Responsable: ${ip}
${seccionIa}
DETALLES TÉCNICOS:
${detalle}

ACCIÓN RECOMENDADA:
${accionOriginal}

⏱️ ID: ${id}${seccionTimestamp}
`.trim();

return [{
  json: {
    text: mensajeFinal,
    codigo_incidente: id,
    tipo_evento: evento,
    severidad: severidad,
    risk_score: parseFloat(score) || 8.0,
    origen_sensor: stripHTML(raw.source || raw.origen || "SOAR Engine"),
    ip_origen: ip,
    activo_afectado: activo,
    detalles_tecnicos: detalle,
    control_nist: control,
    procedimiento_sop: sop || "SOP-04",
    resumen_ia: aiClean || "Análisis estándar aplicado",
    acciones_recomendadas: accionOriginal,
    fecha_registro: nowPeru,
    estado_incidente: "ABIERTO"
  }
}];

// Implementación pura de SHA-256 en JavaScript (sin dependencias externas)
function sha256(ascii) {
    function rightRotate(value, amount) {
        return (value >>> amount) | (value << (32 - amount));
    }
    var mathPow = Math.pow;
    var maxWord = mathPow(2, 32);
    var lengthProperty = 'length';
    var i, j;
    var result = '';
    var words = [];
    var asciiBitLength = ascii[lengthProperty] * 8;
    var hash = [];
    var k = [];
    var primeCounter = 0;
    var isComposite = {};
    for (var candidate = 2; primeCounter < 64; candidate++) {
        if (!isComposite[candidate]) {
            for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
            hash[primeCounter] = (mathPow(candidate, .5) * maxWord) | 0;
            k[primeCounter++] = (mathPow(candidate, 1/3) * maxWord) | 0;
        }
    }
    hash = hash.slice(0, 8);
    ascii += '\x80';
    while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';
    for (i = 0; i < ascii[lengthProperty]; i++) {
        j = ascii.charCodeAt(i);
        if (j >> 8) return; 
        words[i >> 2] |= j << ((3 - i) % 4) * 8;
    }
    words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
    words[words[lengthProperty]] = (asciiBitLength | 0);
    for (j = 0; j < words[lengthProperty];) {
        var w = words.slice(j, j += 16);
        var oldHash = hash;
        hash = hash.slice(0, 8);
        for (i = 0; i < 64; i++) {
            var i2 = i + j;
            var w15 = w[i - 15], w2 = w[i - 2];
            var a = hash[0], e = hash[4];
            var temp1 = hash[7] + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) + ((e & hash[5]) ^ ((~e) & hash[6])) + k[i] + (w[i] = (i < 16) ? w[i] : (
                w[i - 16] + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
            | 0));
            var temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
            hash = [(temp1 + temp2) | 0].concat(hash);
            hash[4] = (hash[4] + temp1) | 0;
        }
        for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
    }
    for (i = 0; i < 8; i++) {
        for (var b = 3; b >= 0; b--) {
            var byte = (hash[i] >> (b * 8)) & 255;
            result += (byte < 16 ? '0' : '') + byte.toString(16);
        }
    }
    return result;
}

const item = $input.first().json;
const cadenaInmutable = `${item.codigo_incidente}:${item.tipo_evento}:${item.severidad}:${item.activo_afectado}:${item.fecha_registro}`;
const hashCalculado = sha256(cadenaInmutable);

return [{
    json: {
        ...item,
        hash_sha256: hashCalculado,
        evento_auditado: `SOAR_DISPATCH: ${item.tipo_evento}`,
        estado_trazabilidad: 'TRAZABILIDAD_GARANTIZADA'
    }
}];
